[
  {
    "id": "c001",
    "name": "Preamble — Parties and Fund",
    "text": "THIS AGREEMENT AND DECLARATION OF TRUST, adopted as of February 20, 1956, and amended and restated, effective as of the September 1, 1993, establishing the Newspaper and’ Mail Deliverers’ -- Publishers’ Pension Fund (the \"Fund\" or \"Plan\"), by and among (a) The Publishers’ Association of New York City (the \"Association\"), acting on behalf of employers in the newspaper delivery industry who are members of the Association, and such other employers which from time. to time become contributing employers hereunder, and their successors and assigns (collectively, the “Employers\") and The Newspaper and Mail Deliverers’ Union of New York and Vicinity and its affiliates and their successors and assigns (collectively, the \"tnion\"), and (b) the following individuals: JOSEPH COTTER, BARBARA KALISH, PATRICK LAGAN, ROBERT NUSSPICKLE, and FRANK SPARACINO, and their successors and assigns (such persons, and others who from time to time are designated hereunder, being hereinafter collectively referred to as the \"Trustees\" of the Fund)."
  },
  {
    "id": "c002",
    "name": "Recital — Collective Bargaining Agreements",
    "text": "WHEREAS, the Union and the Employers have executed, and may from time to time hereafter execute, collective bargaining agreements (\"Collective Bargaining Agreements\") which, among other things, establish the Plan and require periodic Employer contributions to it;"
  },
  {
    "id": "c003",
    "name": "Recital — Trust Agreement and Trustees",
    "text": "WHEREAS, the Collective Bargaining Agreements contenplate that the Union and the Association will execute a Trust Agreement and appoint Trustees;"
  },
  {
    "id": "c004",
    "name": "Recital — Establishment and Purpose of Trust",
    "text": "WHEREAS, to effectuate the aforesaid purpose, this Agreement and Declaration of Trust is made and shall be known as the Newspaper and Mail Deliverers’ -- Publishers’ Pension Fund (the \"Trust,\" \"Fund\" or \"Trust Fund\") to be used for the exclusive purpose of providing pension and retirement benefits to certain employees of the Employers (\"Covered Employees\") and their dependents or beneficiaries (the \"Beneficiaries\") eligible to participate in the Plan;"
  },
  {
    "id": "c005",
    "name": "Recital — Amendment and Restatement",
    "text": "WHEREAS, the Trustees now desire to amend and restate the existing agreement and declaration of trust establishing the Fund, dated February 20, 1956 as amended on June 1, 1976 and from time to time thereafter; and"
  },
  {
    "id": "c006",
    "name": "Recital — Amendment Authority",
    "text": "WHEREAS, Paragraph 18 of the Trust Agreement authorizes the Trustees to amend the provisions of the Trust Agreement."
  },
  {
    "id": "c007",
    "name": "1.1 Administrator",
    "text": "1.1 \"Administrator\" shall mean the Board, or any individual or other person duly authorized by the Board to administer the Plan."
  },
  {
    "id": "c008",
    "name": "1.2 Agreement or Trust Agreement",
    "text": "1.2 \"“Agreement'! or \"Trust Agreement! shall mean the Agreement and Declaration of Trust establishing the Newspaper and Mail Deliverers’-~Publishers’ Pension Fund adopted as of February 20, 1956, as from time to time amended and restated, which constitutes the funding vehicle for the Plan for the benefit of Covered Employees and certain of their Beneficiaries."
  },
  {
    "id": "c009",
    "name": "1.3 Association",
    "text": "1.3 \"Association\" shall mean the Publishers’ Association of New York."
  },
  {
    "id": "c010",
    "name": "1.4 Authorized Person",
    "text": "1.4 “Authorized Person\"! shall mean, with respect to the Trust Fund, both the Chairman and Secretary of the Board, any individual Trustee or member of any Committee of Trustees duly authorized by the Board to represent said Committee or the Board, and the Administrator where the Administrator has been duly authorized by the Board to represent the Board or the Trust Fund in a specific matter (or their duly authorized agents). With respect to an Investment Manager Account, the term \"Authorized Person\" shall mean any officer (or partner) of the Investment Manager duly appointed by the Board to manage the assets of such Investment Manager Account or any other person or persons as may be duly designated by such officer (or partner). With respect to a Custodian, the term \"Authorized Person\" shall mean any officer of said Custodian."
  },
  {
    "id": "c011",
    "name": "1.5 Beneficiary",
    "text": "1.5 \"Beneficiary\" shall mean a Covered Employee's spouse, or such other person or entity who, as a result of his relationship to the Covered Employee, is entitled under the terms of the Plan to receive benefits, if any, under the Plan following the death of the Covered Employee."
  },
  {
    "id": "c012",
    "name": "1.6 Board",
    "text": "1.6 “Board shall mean the individuals from time to time acting collectively as the Board of Trustees under this Agreement, which shall also be the \"named fiduciary\" (as that term is defined in Section 402(a)(2) of ERISA) and the \"administrator\" (as that term is defined. in Section 3(16) (A) of ERISA) of the Plan, appointed to control and manage the operation and overall administration of the Plan and the Trust Fund."
  },
  {
    "id": "c013",
    "name": "1.7 Code",
    "text": "1.7 \"Code\" shall mean the Internal Revenue Code of 1936, as from time to time amended, and all rules, regulations and interpretations promulgated pursuant thereto."
  },
  {
    "id": "c014",
    "name": "1.8 Collective Bargaining Agreement",
    "text": "1.8 \"Collective Bargaining Agreement\" shall mean, collectively, each collective bargaining agreement, participation agreement, or other written agreement between an Employer and the Union, which is in force and effect and is acceptable to the Board, requiring contributions to be made to this Trust Fund on behalf of a Covered Employee (and/or a Beneficiary)."
  },
  {
    "id": "c015",
    "name": "1.9 Collective Trust",
    "text": "‘1.9 \"Collective Trust\" shall mean any pooled, group, common, commingled or collective trust fund maintained by a bank, trust company or broker-dealer. The trustees of such Collective Trust shall become trustees of the allocable share of the Trust Fund assets transferred and deposited with such Collective Trust, and shall have sole and exclusive authority and discretion to manage and control (including the power to invest and reinvest) such assets. The Board shall not be liable for any act or omission of any trustee of a Collective Trust, or be under any obligation to invest or otherwise manage any assets of the Trust Fund that have been transferred thereto. The provisions of the agreement establishing such Collective Trust shall be deemed to be incorporated by reference into this Agreement (to the extent that the provisions thereof are not inconsistent with the terms of this Agreement)."
  },
  {
    "id": "c016",
    "name": "1.10 Committee",
    "text": "21.10 \"Committee\" shall mean any committee duly appointed and authorized by the Board pursuant to this Agreement (containing at least one Employer Trustee and one Union Trustee)."
  },
  {
    "id": "c017",
    "name": "1.11 Covered Employee",
    "text": "1.11 \"Covered Employee\" shall mean an individual employed by an Employer who is covered under the terms of a Collective Bargaining Agreement between the Employer and the Union requiring contributions to the Fund on behalf of said individual."
  },
  {
    "id": "c018",
    "name": "1.12 Custodian",
    "text": "1.12 \"Custodian\" shall mean one or more banks, trust companies, or broker-dealers selected by the Board as a \"Corpo~ rate Trustee\" (as that term is defined in Section 3.12) and/or custodian of Trust Fund Securities."
  },
  {
    "id": "c019",
    "name": "1.13 Employer",
    "text": "1.13 \"Employer\" or \"Employers\" or \"Contributing Employers® shall mean any employer required to contribute to the Plan on behalf of Covered Employees pursuant to a Collective Bargaining Agreement with the Union."
  },
  {
    "id": "c020",
    "name": "1.14 Employer Trustee",
    "text": "1.14 \"Employer Trustee\" shall mean each individual designated as an Employer Trustee pursuant to Section 3.3(a), and their successors and assigns."
  },
  {
    "id": "c021",
    "name": "1.15 ERISA",
    "text": "1.15 \"ERISA\" shall mean the Employee Retirement Income Security Act of 1974, as. from time to time. anended, and alt rules and regulations promulgated. pursuant thereto..."
