 ]},
 {"clause_id": "c115", "issues": [
   {"issue": "This section makes the fiduciary acknowledgment optional (\"may require\"), while Section 1.18 makes a written acknowledgment to the Board a defining condition of being an \"Investment Manager.\" Whether a manager without an acknowledgment is an Investment Manager, and thus whether the Board's disclaimers in Sections 8.5 and 8.8 apply to it, cannot be answered from either alone.", "type": 2, "prob": 0.25}
 ]},
 {"clause_id": "c116", "issues": [
