 ]},
 {"clause_id": "c125", "issues": []},
 {"clause_id": "c126", "issues": [
   {"issue": "The sentence that \"[t]he costs and expenses incurred in the collection of Employer contributions shall be paid from the Fund\" cannot be squared with Section 9.4(b), Section 9.5(b) and Section 9.7(d), which place those same collection costs, counsel fees and court costs on the delinquent Employer. Who ultimately bears collection costs turns on reconciling them.", "type": 2, "prob": 0.26}
 ]},
 {"clause_id": "c127", "issues": [
